    $("#mainContents").empty().append(data);
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeTitleOfAccountPanel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeTitleOfAccountPanel = function () {
    /* sdd-asis-lifecycle:begin changeTitleOfAccountPanel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let val = $c.util.getComponent('slc_fininfotype').getValue(); if (val == null) { val = ''; }
    if (val === "finstat") {
        scwin.title_of_account1.setStyle("display", "");
        scwin.title_of_account2.setStyle("display", "none");
        $c.util.getComponent('ipt_finsearchtype').setValue("finstat");
        $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finstat[0]);
        $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
    } else {
        if (val === "finrate") {
            scwin.title_of_account1.setStyle("display", "none");
            scwin.title_of_account2.setStyle("display", "");
            $c.util.getComponent('ipt_finsearchtype').setValue("finrate");
            $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finrate[0]);
            $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.makeTitleOfAccountParamString
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.makeTitleOfAccountParamString = function () {
    /* sdd-asis-lifecycle:begin makeTitleOfAccountParamString — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var paramString = "";
    let flag = false;
    var paramString = "";
    const finsearchtype = $c.util.getComponent('ipt_finsearchtype').getValue();
    if (finsearchtype === "finstat") {
        for (var i = 0; i < scwin.finstat.length; i++) {
            flag = scwin.checkChkBoxStatus(scwin.finstat[i]);
            if (flag) {
                paramString += scwin.finstat[i];
                if (i !== (scwin.finstat.length - 1)) {
                    paramString += "|";
                }
            }
        }
    } else {
        if (finsearchtype === "finrate") {
            for (var i = 0; i < scwin.finrate.length; i++) {
                flag = scwin.checkChkBoxStatus(scwin.finrate[i]);
                if (flag) {
                    paramString += scwin.finrate[i];
                    if (i !== (scwin.finrate.length - 1)) {
                        paramString += "|";
                    }
                }
            }
        }
    }
    return paramString;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkChkBoxStatus
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.checkChkBoxStatus = function (id) {
    /* sdd-asis-lifecycle:begin checkChkBoxStatus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return $("#" + id).is(":checked");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeAllCheckState
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeAllCheckState = function () {
    /* sdd-asis-lifecycle:begin changeAllCheckState — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let val = $c.util.getComponent('slc_fininfotype').getValue(); if (val == null) { val = ''; }
    if (val === "finstat") {
        for (var i = 0; i < scwin.finstat.length; i++) {
            if ($("#ipt_chAll1").is(":checked")) {
                $("#" + scwin.finstat[i]).attr("checked", true);
            } else {
                $("#" + scwin.finstat[i]).attr("checked", false);
            }
        }
    } else {
        if (val === "finrate") {
            for (var i = 0; i < scwin.finrate.length; i++) {
                if ($("#ipt_chAll2").is(":checked")) {
                    $("#" + scwin.finrate[i]).attr("checked", true);
                } else {
                    $("#" + scwin.finrate[i]).attr("checked", false);
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download_corps");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download_corps");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnFindCompanySelect
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnFindCompanySelect = function () {
    /* sdd-asis-lifecycle:begin fnFindCompanySelect — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const wUrl = "/compfinance/financialinfo.do?method=searchFinancialInfoOfCorpSelect";
    $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), { id: "회사선택", width: "725", height: "600", scrollbars: true, resizable: false, type: "pageFramePopup" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpBasicInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpBasicInfo = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpBasicInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", val);
        console.warn('[sdd] 미실현(재설계 분류 #128): fnAKCKwdSearchCorpName(' + "" + ')');
    } else {
        await $c.win.alert("조회할 회사명을 입력해 주세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items.length == 1) {
        await scwin.fnSearchCorpCode(items[0]);
    } else {
        if (items.length > 1) {
            scwin.fnFindCompanySelect();
        } else {
            await scwin.fnSearchCorpCode(null);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
    } else {
        const comabbr = items.comabbrv;
        const isurcd = items.isurcd;
        const repisusrtcd2 = items.repisusrtcd2;
        const spotisutrdmkttpcd = items.spotisutrdmkttpcd;
        const liststatcd = items.liststatcd;
        let mkttpimg = "";
        if (spotisutrdmkttpcd === "1") {
            mkttpimg = "<img src='../images/common/icn_t_yu.gif' class='vmiddle' alt='유가증권' />&nbsp;";
        } else {
            if (spotisutrdmkttpcd === "2") {
                mkttpimg = "<img src='../images/common/icn_t_ko.gif' class='vmiddle' alt='코스닥' />&nbsp;";
            } else {
                if (spotisutrdmkttpcd === "6") {
                    mkttpimg = "<img src='../images/common/icn_t_konex.gif' class='vmiddle' alt='코넥스' />&nbsp;";
                }
            }
        }
        let liststatimg = "";
        if (liststatcd === 'D') {
            liststatimg = "<img src='../images/common/icn_t_pe.gif' class='vmiddle' alt='폐' />";
        }
        const vTr = $("<tr />");
        vTr.attr("style", "cursor: pointer;");
        const vTd = $("<td />");
        vTd.addClass("first txc");
        const vInput1 = $("<input type='hidden' id='arrIsurCd' name='arrIsurCd' />");
        vInput1.val(isurcd);
        const vInput2 = $("<input type='hidden' id='stkCd' />");
        vInput2.val(repisusrtcd2 + "|" + comabbr);
        vTd.append(vInput1);
        vTd.append(vInput2);
        const vSpan = $("<span />");
        vSpan.addClass("dvs");
        vSpan.html(repisusrtcd2);
        vTd.append(vSpan);
        const vTd2 = $("<td />");
        vTd2.attr("id", "sub");
        vTd2.append(mkttpimg + "" + comabbr + "&nbsp;" + liststatimg);
        vTr.append(vTd);
        vTr.append(vTd2);
        let vChk = false;
        $('#txt_addStockHtml').find('input:hidden[name=arrIsurCd]').each(function() {
                if ($(this).val() === isurcd) {
                    vChk = true;
                }
        });
        if (vChk) {
            await $c.win.alert('동일한 회사명이 있습니다.');
        } else {
            if ($('#txt_addStockHtml').find('tr').length < 10) {
                $('#txt_addStockHtml').append(vTr);
                scwin.fnAddStock($c.util.getComponent('txt_addStockHtml').getValue());
            } else {
                await $c.win.alert('회사명을 최대 10개이므로 추가할 수 없습니다.');
            }
        }
    }
    $c.util.getComponent('AKCKwd').setValue('');
    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnAddStock
 * @author Inswave
 * @date 2026. 09. 29
 * @param html
 * @returns
 * @hidden N
*/
scwin.fnAddStock = function (html) {
    /* sdd-asis-lifecycle:begin fnAddStock — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($.trim(html) !== "") {
        let spanHtml = "";
        (($c.util.getComponent('txt_addStockHtml')) && ($c.util.getComponent('txt_addStockHtml')).setValue ? ($c.util.getComponent('txt_addStockHtml')).setValue(html) : (($c.util.getComponent('txt_addStockHtml')) && ($c.util.getComponent('txt_addStockHtml')).setText ? ($c.util.getComponent('txt_addStockHtml')).setText(html) : void (html)));
        $('#txt_addStockHtml').find('td[id=sub]').each(function() {
                spanHtml += '<li>' + $(this).html() + '</li>';
        });
        $('#addSearch').find('ul').html(spanHtml);
        scwin.addSearch.setStyle("display", "");
        scwin.addSearchTop.setStyle("display", "");
    } else {
        $c.util.getComponent('txt_addStockHtml').setLabel("");
        console.error("[sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_label — {target}.setLabel({args}) */
        scwin.addSearch.setStyle("display", "none");
        scwin.addSearchTop.setStyle("display", "none");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnGetAddStock
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnGetAddStock = function () {
    /* sdd-asis-lifecycle:begin fnGetAddStock — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return $c.util.getComponent('txt_addStockHtml').getValue();
    /* sdd-asis-lifecycle:end */
};
